// AscendC TanhGatedResidualAddBackward kernel — pure Vector operator
// Supports bfloat16 (inputs/outputs), float32 internal compute
// Two-phase: phase1 (element-wise + partial sum) + phase2 (grad_gate w/ scalar_s)
// Format: Abs-style with dtype dispatch in __global__ entry

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t BLOCK_ELEMS = 2048;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) { return 0U; }
    return (a + b - 1U) / b;
}

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    const AscendC::GlobalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    const AscendC::GlobalTensor<T> &dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

template <typename T>
__aicore__ inline void PrepareInputFloat32(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &src,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

template <typename T>
__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
{
    if constexpr (std::is_same_v<T, bfloat16_t>) {
        return AscendC::RoundMode::CAST_ROUND;
    }
    return AscendC::RoundMode::CAST_NONE;
}

template <typename T>
__aicore__ inline void FinalizeOutput(
    AscendC::LocalTensor<T> &out,
    AscendC::LocalTensor<float> &src,
    int32_t count)
{
    if constexpr (!std::is_same_v<T, float>) {
        AscendC::Cast(out, src, OutputRoundModeHelper<T>(), count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

// =========================================================================
// Phase 1 kernel: element-wise + partial sum
// Computes grad_residual and grad_hidden_states; writes partial sums to workspace
// =========================================================================

template <typename dataType>
class TanhGatedBackwardPhase1Kernel {
public:
    __aicore__ inline void Init(
        GM_ADDR grad_output, GM_ADDR gate, GM_ADDR hidden_states, GM_ADDR mask,
        GM_ADDR grad_residual, GM_ADDR grad_hidden_states,
        GM_ADDR workspace,
        int32_t totalElems, int32_t usedCoreNum, int32_t tasksPerCore)
    {
        totalElems_ = totalElems;
        usedCoreNum_ = usedCoreNum;
        tasksPerCore_ = tasksPerCore;

        goGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(grad_output), totalElems);
        gGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gate), totalElems);
        hsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(hidden_states), totalElems);
        mGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(mask), totalElems);
        grGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(grad_residual), totalElems);
        ghGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(grad_hidden_states), totalElems);
        wsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(workspace), usedCoreNum);

        if ASCEND_IS_AIV {
            // Input queues
            pipe.InitBuffer(goInQueue_, BUFFER_NUM, BLOCK_ELEMS * sizeof(dataType));
            pipe.InitBuffer(gInQueue_, BUFFER_NUM, BLOCK_ELEMS * sizeof(dataType));
            pipe.InitBuffer(hsInQueue_, BUFFER_NUM, BLOCK_ELEMS * sizeof(dataType));
            pipe.InitBuffer(mInQueue_, BUFFER_NUM, BLOCK_ELEMS * sizeof(dataType));

            // Output queues
            pipe.InitBuffer(grOutQueue_, BUFFER_NUM, BLOCK_ELEMS * sizeof(dataType));
            pipe.InitBuffer(ghOutQueue_, BUFFER_NUM, BLOCK_ELEMS * sizeof(dataType));

            // Intermediate float32 buffers
            pipe.InitBuffer(goF32Buf_, BLOCK_ELEMS * sizeof(float));
            pipe.InitBuffer(gF32Buf_, BLOCK_ELEMS * sizeof(float));
            pipe.InitBuffer(hsF32Buf_, BLOCK_ELEMS * sizeof(float));
            pipe.InitBuffer(mF32Buf_, BLOCK_ELEMS * sizeof(float));
            pipe.InitBuffer(tmp1F32Buf_, BLOCK_ELEMS * sizeof(float));
            pipe.InitBuffer(tmp2F32Buf_, BLOCK_ELEMS * sizeof(float));
            pipe.InitBuffer(tmp3F32Buf_, BLOCK_ELEMS * sizeof(float));

            // Reduce work buffer
            pipe.InitBuffer(reduceBuf_, 2 * BLOCK_ELEMS * sizeof(uint8_t));
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int32_t coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();

            float partialSum = 0.0f;

            for (int32_t t = 0; t < tasksPerCore_; t++) {
                int32_t tileStart = coreIdx * tasksPerCore_ * BLOCK_ELEMS + t * BLOCK_ELEMS;
                if (tileStart >= totalElems_) { break; }
                int32_t tileEnd = (tileStart + BLOCK_ELEMS > totalElems_) ? totalElems_ : (tileStart + BLOCK_ELEMS);
                int32_t tileLen = tileEnd - tileStart;

                CopyInPhase1(tileStart, tileLen);
                float tileSum = ComputePhase1(tileLen);
                CopyOutPhase1(tileStart, tileLen);

                partialSum += tileSum;
            }

            // Write partial sum to workspace (at coreIdx, which is the block index for AIV-only)
            int32_t blockIdxInAiv = coreIdx;
            // Use scalar write
            AscendC::LocalTensor<float> sumLocal = sumBuf_.Get<float>();
            sumLocal.SetValue(0, partialSum);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::DataCopyExtParams cp{1, static_cast<uint32_t>(sizeof(float)), 0, 0, 0};
            AscendC::DataCopyPad(wsGM_[blockIdxInAiv], sumLocal, cp);
            AscendC::PipeBarrier<PIPE_MTE2>();
        }
    }

private:
    __aicore__ inline void CopyInPhase1(int32_t tileStart, int32_t tileLen)
    {
        // Allocate all 4 input tensors
        goInLocal_ = goInQueue_.AllocTensor<dataType>();
        gInLocal_ = gInQueue_.AllocTensor<dataType>();
        hsInLocal_ = hsInQueue_.AllocTensor<dataType>();
        mInLocal_ = mInQueue_.AllocTensor<dataType>();

        LoadGmToUb(goInLocal_, goGM_[tileStart], static_cast<uint32_t>(tileLen));
        LoadGmToUb(gInLocal_, gGM_[tileStart], static_cast<uint32_t>(tileLen));
        LoadGmToUb(hsInLocal_, hsGM_[tileStart], static_cast<uint32_t>(tileLen));
        LoadGmToUb(mInLocal_, mGM_[tileStart], static_cast<uint32_t>(tileLen));

        goInQueue_.EnQue(goInLocal_);
        gInQueue_.EnQue(gInLocal_);
        hsInQueue_.EnQue(hsInLocal_);
        mInQueue_.EnQue(mInLocal_);
    }

    __aicore__ inline float ComputePhase1(int32_t tileLen)
    {
        // === Allocate output queues ===
        grOutLocal_ = grOutQueue_.AllocTensor<dataType>();
        ghOutLocal_ = ghOutQueue_.AllocTensor<dataType>();

        // === Get buffer references ===
        AscendC::LocalTensor<float> goF32 = goF32Buf_.Get<float>();
        AscendC::LocalTensor<float> gF32 = gF32Buf_.Get<float>();
        AscendC::LocalTensor<float> hsF32 = hsF32Buf_.Get<float>();
        AscendC::LocalTensor<float> mF32 = mF32Buf_.Get<float>();
        AscendC::LocalTensor<float> tmp1 = tmp1F32Buf_.Get<float>();
        AscendC::LocalTensor<float> tmp2 = tmp2F32Buf_.Get<float>();
        AscendC::LocalTensor<float> tmp3 = tmp3F32Buf_.Get<float>();
        AscendC::LocalTensor<uint8_t> reduceTmp = reduceBuf_.Get<uint8_t>();
        AscendC::LocalTensor<float> sumLocal = sumBuf_.Get<float>();

        // === DeQue inputs ===
        goInLocal_ = goInQueue_.DeQue<dataType>();
        gInLocal_ = gInQueue_.DeQue<dataType>();
        hsInLocal_ = hsInQueue_.DeQue<dataType>();
        mInLocal_ = mInQueue_.DeQue<dataType>();

        // === Cast inputs to float32 ===
        PrepareInputFloat32<dataType>(goF32, goInLocal_, goF32Buf_, tileLen);
        PrepareInputFloat32<dataType>(gF32, gInLocal_, gF32Buf_, tileLen);
        PrepareInputFloat32<dataType>(hsF32, hsInLocal_, hsF32Buf_, tileLen);
        PrepareInputFloat32<dataType>(mF32, mInLocal_, mF32Buf_, tileLen);

        // === Compute tanh(gate) = (exp(2*g) - 1) / (exp(2*g) + 1) ===
        // tmp1 = 2 * gate
        AscendC::Muls(tmp1, gF32, 2.0f, tileLen);
        // tmp2 = exp(2 * gate)
        AscendC::Exp(tmp2, tmp1, tileLen);
        // tmp1 = exp(2*g) + 1
        AscendC::Adds(tmp1, tmp2, 1.0f, tileLen);
        // tmp3 = exp(2*g) - 1
        AscendC::Adds(tmp3, tmp2, -1.0f, tileLen);
        // gF32 = tanh(gate) = (exp(2*g) - 1) / (exp(2*g) + 1)
        AscendC::Div(gF32, tmp3, tmp1, tileLen);

        // === Compute grad_hidden_states = grad_output * tanh(gate) * mask ===
        // tmp1 = grad_output * tanh(gate)
        AscendC::Mul(tmp1, goF32, gF32, tileLen);
        // tmp1 = grad_output * tanh(gate) * mask
        AscendC::Mul(tmp1, tmp1, mF32, tileLen);

        // === Store grad_residual (identity of grad_output) ===
        FinalizeOutput<dataType>(grOutLocal_, goF32, tileLen);

        // === Store grad_hidden_states ===
        FinalizeOutput<dataType>(ghOutLocal_, tmp1, tileLen);

        // === Compute partial sum = sum(grad_output * hidden_states * mask) ===
        // tmp2 = grad_output * hidden_states
        AscendC::Mul(tmp2, goF32, hsF32, tileLen);
        // tmp2 = grad_output * hidden_states * mask
        AscendC::Mul(tmp2, tmp2, mF32, tileLen);

        // Reduce sum over tile
        AscendC::ReduceSum<float>(sumLocal, tmp2, reduceTmp, tileLen);
        float tileSum = sumLocal.GetValue(0);

        // === EnQue outputs ===
        grOutQueue_.EnQue(grOutLocal_);
        ghOutQueue_.EnQue(ghOutLocal_);

        // === Free input tensors ===
        goInQueue_.FreeTensor(goInLocal_);
        gInQueue_.FreeTensor(gInLocal_);
        hsInQueue_.FreeTensor(hsInLocal_);
        mInQueue_.FreeTensor(mInLocal_);

        return tileSum;
    }

    __aicore__ inline void CopyOutPhase1(int32_t tileStart, int32_t tileLen)
    {
        grOutLocal_ = grOutQueue_.DeQue<dataType>();
        ghOutLocal_ = ghOutQueue_.DeQue<dataType>();

        StoreUbToGm(grGM_[tileStart], grOutLocal_, static_cast<uint32_t>(tileLen));
        StoreUbToGm(ghGM_[tileStart], ghOutLocal_, static_cast<uint32_t>(tileLen));

        grOutQueue_.FreeTensor(grOutLocal_);
        ghOutQueue_.FreeTensor(ghOutLocal_);
    }

private:
    int32_t totalElems_ = 0;
    int32_t usedCoreNum_ = 0;
    int32_t tasksPerCore_ = 0;

    AscendC::TPipe pipe;

    AscendC::GlobalTensor<dataType> goGM_;
    AscendC::GlobalTensor<dataType> gGM_;
    AscendC::GlobalTensor<dataType> hsGM_;
    AscendC::GlobalTensor<dataType> mGM_;
    AscendC::GlobalTensor<dataType> grGM_;
    AscendC::GlobalTensor<dataType> ghGM_;
    AscendC::GlobalTensor<float> wsGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> goInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> gInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> hsInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> mInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> grOutQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> ghOutQueue_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> goF32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> gF32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> hsF32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> mF32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmp1F32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmp2F32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmp3F32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;

    AscendC::LocalTensor<dataType> goInLocal_;
    AscendC::LocalTensor<dataType> gInLocal_;
    AscendC::LocalTensor<dataType> hsInLocal_;
    AscendC::LocalTensor<dataType> mInLocal_;
    AscendC::LocalTensor<dataType> grOutLocal_;
    AscendC::LocalTensor<dataType> ghOutLocal_;
};

// =========================================================================
// Phase 2 kernel: grad_gate = scalar_s * (1 - tanh(gate)^2)
// scalar_s is passed as a kernel parameter (computed by host from phase1 workspace)
// =========================================================================

template <typename dataType>
class TanhGatedBackwardPhase2Kernel {
public:
    __aicore__ inline void Init(
        GM_ADDR gate, GM_ADDR grad_gate,
        int32_t totalElems, int32_t usedCoreNum, int32_t tasksPerCore, float scalarS)
    {
        totalElems_ = totalElems;
        usedCoreNum_ = usedCoreNum;
        tasksPerCore_ = tasksPerCore;
        scalarS_ = scalarS;

        gGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gate), totalElems);
        ggGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(grad_gate), totalElems);

        if ASCEND_IS_AIV {
            pipe.InitBuffer(gInQueue_, BUFFER_NUM, BLOCK_ELEMS * sizeof(dataType));
            pipe.InitBuffer(ggOutQueue_, BUFFER_NUM, BLOCK_ELEMS * sizeof(dataType));
            pipe.InitBuffer(gF32Buf_, BLOCK_ELEMS * sizeof(float));
            pipe.InitBuffer(tmp1F32Buf_, BLOCK_ELEMS * sizeof(float));
            pipe.InitBuffer(tmp2F32Buf_, BLOCK_ELEMS * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int32_t coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();

            for (int32_t t = 0; t < tasksPerCore_; t++) {
                int32_t tileStart = coreIdx * tasksPerCore_ * BLOCK_ELEMS + t * BLOCK_ELEMS;
                if (tileStart >= totalElems_) { break; }
                int32_t tileEnd = (tileStart + BLOCK_ELEMS > totalElems_) ? totalElems_ : (tileStart + BLOCK_ELEMS);
                int32_t tileLen = tileEnd - tileStart;

                CopyInPhase2(tileStart, tileLen);
                ComputePhase2(tileLen);
                CopyOutPhase2(tileStart, tileLen);
            }
        }
    }

private:
    __aicore__ inline void CopyInPhase2(int32_t tileStart, int32_t tileLen)
    {
        gInLocal_ = gInQueue_.AllocTensor<dataType>();
        LoadGmToUb(gInLocal_, gGM_[tileStart], static_cast<uint32_t>(tileLen));
        gInQueue_.EnQue(gInLocal_);
    }

    __aicore__ inline void ComputePhase2(int32_t tileLen)
    {
        ggOutLocal_ = ggOutQueue_.AllocTensor<dataType>();

        AscendC::LocalTensor<float> gF32 = gF32Buf_.Get<float>();
        AscendC::LocalTensor<float> tmp1 = tmp1F32Buf_.Get<float>();
        AscendC::LocalTensor<float> tmp2 = tmp2F32Buf_.Get<float>();

        gInLocal_ = gInQueue_.DeQue<dataType>();
        PrepareInputFloat32<dataType>(gF32, gInLocal_, gF32Buf_, tileLen);

        // === Compute tanh(gate) ===
        // tmp1 = 2 * gate
        AscendC::Muls(tmp1, gF32, 2.0f, tileLen);
        // tmp2 = exp(2 * gate)
        AscendC::Exp(tmp2, tmp1, tileLen);
        // tmp1 = exp(2*g) + 1
        AscendC::Adds(tmp1, tmp2, 1.0f, tileLen);
        // gF32 = exp(2*g) - 1
        AscendC::Adds(gF32, tmp2, -1.0f, tileLen);
        // tmp2 = tanh(gate) = (exp(2*g) - 1) / (exp(2*g) + 1)
        AscendC::Div(tmp2, gF32, tmp1, tileLen);

        // === Compute sech_squared = 1 - tanh(gate)^2 ===
        // tmp1 = tanh(gate)^2
        AscendC::Mul(tmp1, tmp2, tmp2, tileLen);
        // tmp1 = 1 - tanh(gate)^2 = sech_squared
        AscendC::Muls(tmp1, tmp1, -1.0f, tileLen);
        AscendC::Adds(tmp1, tmp1, 1.0f, tileLen);

        // === grad_gate = scalar_s * sech_squared ===
        AscendC::Muls(tmp1, tmp1, scalarS_, tileLen);

        // === Store grad_gate ===
        FinalizeOutput<dataType>(ggOutLocal_, tmp1, tileLen);

        ggOutQueue_.EnQue(ggOutLocal_);
        gInQueue_.FreeTensor(gInLocal_);
    }

    __aicore__ inline void CopyOutPhase2(int32_t tileStart, int32_t tileLen)
    {
        ggOutLocal_ = ggOutQueue_.DeQue<dataType>();
        StoreUbToGm(ggGM_[tileStart], ggOutLocal_, static_cast<uint32_t>(tileLen));
        ggOutQueue_.FreeTensor(ggOutLocal_);
    }

private:
    int32_t totalElems_ = 0;
    int32_t usedCoreNum_ = 0;
    int32_t tasksPerCore_ = 0;
    float scalarS_ = 0.0f;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> gGM_;
    AscendC::GlobalTensor<dataType> ggGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> gInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> ggOutQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> gF32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmp1F32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmp2F32Buf_;

    AscendC::LocalTensor<dataType> gInLocal_;
    AscendC::LocalTensor<dataType> ggOutLocal_;
};

// =========================================================================
// Dtype dispatch helpers
// =========================================================================

template <template <typename> class Kernel, typename... ExtraArgs>
__aicore__ inline void DispatchKernel(
    GM_ADDR go, GM_ADDR g, GM_ADDR hs, GM_ADDR m,
    GM_ADDR gr, GM_ADDR gh, GM_ADDR ws,
    int32_t totalElems, int32_t usedCoreNum, int32_t tasksPerCore,
    int64_t dtypeFlag, ExtraArgs... extraArgs)
{
    if (dtypeFlag == 1) {
        Kernel<half> kernel;
        kernel.Init(go, g, hs, m, gr, gh, ws, totalElems, usedCoreNum, tasksPerCore, extraArgs...);
        kernel.Process();
    } else {
        Kernel<bfloat16_t> kernel;
        kernel.Init(go, g, hs, m, gr, gh, ws, totalElems, usedCoreNum, tasksPerCore, extraArgs...);
        kernel.Process();
    }
}

// =========================================================================
// Kernel entry points
// dtypeFlag: 0=fp32, 1=fp16, 2=bf16
// =========================================================================

extern "C" __global__ __aicore__ void tanh_gated_residual_add_backward_phase1(
    GM_ADDR grad_output, GM_ADDR gate, GM_ADDR hidden_states, GM_ADDR mask,
    GM_ADDR grad_residual, GM_ADDR grad_hidden_states,
    GM_ADDR workspace,
    int32_t totalElems, int32_t usedCoreNum, int32_t tasksPerCore,
    int64_t dtypeFlag)
{
    DispatchKernel<TanhGatedBackwardPhase1Kernel>(
        grad_output, gate, hidden_states, mask,
        grad_residual, grad_hidden_states, workspace,
        totalElems, usedCoreNum, tasksPerCore, dtypeFlag);
}

extern "C" __global__ __aicore__ void tanh_gated_residual_add_backward_phase2(
    GM_ADDR gate, GM_ADDR grad_gate,
    int32_t totalElems, int32_t usedCoreNum, int32_t tasksPerCore,
    float scalarS, int64_t dtypeFlag)
{
    if (dtypeFlag == 1) {
        TanhGatedBackwardPhase2Kernel<half> kernel;
        kernel.Init(gate, grad_gate, totalElems, usedCoreNum, tasksPerCore, scalarS);
        kernel.Process();
    } else {
        TanhGatedBackwardPhase2Kernel<bfloat16_t> kernel;
        kernel.Init(gate, grad_gate, totalElems, usedCoreNum, tasksPerCore, scalarS);
        kernel.Process();
    }
}
