// TanhGatedResidualAddBackward op_host — tiling calculation + two-phase kernel launch
// Format: Abs-style with platform_ascendc and EXEC_KERNEL_CMD

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_tanh_gated_residual_add_backward_phase1.h"
#include "aclrtlaunch_tanh_gated_residual_add_backward_phase2.h"

// ---------------------------------------------------------------------------
// Tiling constants
// ---------------------------------------------------------------------------

constexpr int32_t DEFAULT_BLOCK_ELEMS = 2048;
constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;

namespace ascend_kernel {

std::vector<at::Tensor> tanh_gated_residual_add_backward(
    const at::Tensor &grad_output,
    const at::Tensor &gate,
    const at::Tensor &hidden_states,
    const at::Tensor &mask)
{
    // Input validation
    TORCH_CHECK(grad_output.dtype() == at::kBFloat16,
        "grad_output must be bfloat16");
    TORCH_CHECK(gate.dtype() == at::kBFloat16,
        "gate must be bfloat16");
    TORCH_CHECK(hidden_states.dtype() == at::kBFloat16,
        "hidden_states must be bfloat16");
    TORCH_CHECK(mask.dtype() == at::kBFloat16,
        "mask must be bfloat16");
    TORCH_CHECK(grad_output.sizes() == gate.sizes(),
        "grad_output and gate must have the same shape");
    TORCH_CHECK(grad_output.sizes() == hidden_states.sizes(),
        "grad_output and hidden_states must have the same shape");
    TORCH_CHECK(grad_output.sizes() == mask.sizes(),
        "grad_output and mask must have the same shape");
    TORCH_CHECK(grad_output.is_contiguous(), "grad_output must be contiguous");

    int64_t totalElems = grad_output.numel();
    int32_t totalElems32 = static_cast<int32_t>(totalElems);

    // Tiling: split elements across cores
    int32_t elemNum = (totalElems32 + DEFAULT_BLOCK_ELEMS - 1) / DEFAULT_BLOCK_ELEMS;
    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES,
        std::max<int32_t>(1, elemNum));
    int32_t tasksPerCore = (elemNum + usedCoreNum - 1) / usedCoreNum;

    // Allocate output tensors (flattened)
    auto options = grad_output.options();
    at::Tensor grad_residual = at::empty_like(grad_output);
    at::Tensor grad_hidden_states = at::empty_like(grad_output);
    at::Tensor grad_gate = at::empty_like(grad_output);

    // Workspace for partial sums (one float per core)
    at::Tensor workspace = at::empty({usedCoreNum}, options.dtype(at::kFloat));

    // dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 2;  // bf16

    // All tiling params as left values (required by EXEC_KERNEL_CMD)
    int32_t blockElems = DEFAULT_BLOCK_ELEMS;
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // === Phase 1: element-wise + partial sums ===
    EXEC_KERNEL_CMD(tanh_gated_residual_add_backward_phase1, blockDim,
                    grad_output, gate, hidden_states, mask,
                    grad_residual, grad_hidden_states,
                    workspace,
                    totalElems32, usedCoreNum, tasksPerCore,
                    dtypeFlag);

    // === Host-side: compute global scalar_s from workspace partial sums ===
    float *wsPtr = workspace.data_ptr<float>();
    float scalarS = 0.0f;
    for (int32_t i = 0; i < usedCoreNum; i++) {
        scalarS += wsPtr[i];
    }

    // === Phase 2: grad_gate = scalar_s * (1 - tanh(gate)^2) ===
    float scalarSVal = scalarS;
    EXEC_KERNEL_CMD(tanh_gated_residual_add_backward_phase2, blockDim,
                    gate, grad_gate,
                    totalElems32, usedCoreNum, tasksPerCore,
                    scalarSVal, dtypeFlag);

    return {grad_residual, grad_hidden_states, grad_gate};
}

}  // namespace ascend_kernel
